import app from 'flarum/admin/app';
const networks = ['facebook', 'twitter', 'linkedin', 'reddit', 'whatsapp', 'telegram', 'vkontakte', 'odnoklassniki', 'my_mail', 'qq', 'qzone', 'native'];
app.initializers.add('fof/share-social', () => {
  const set = app.registry.for('fof-share-social').registerSetting({
    label: app.translator.trans('fof-share-social.admin.settings.canonical-urls'),
    setting: 'fof-share-social.canonical-urls',
    type: 'boolean'
  }).registerSetting({
    label: app.translator.trans('fof-share-social.admin.settings.plain-copy'),
    setting: 'fof-share-social.plain-copy',
    type: 'boolean'
  }).registerSetting({
    label: app.translator.trans('fof-share-social.admin.settings.default-option'),
    help: app.translator.trans('fof-share-social.admin.settings.default-option-help'),
    setting: 'fof-share-social.default-option',
    type: 'select',
    options: networks.reduce((o, network) => {
      o[network] = app.translator.trans("fof-share-social.lib.networks.".concat(network));
      return o;
    }, {
      '': ''
    })
  }).registerSetting(function () {
    return m("hr", null);
  });
  networks.forEach(network => set.registerSetting({
    label: app.translator.trans("fof-share-social.lib.networks.".concat(network)),
    setting: "fof-share-social.networks.".concat(network),
    type: 'boolean'
  }));
});